import Image from "next/image";
import { cn } from "@/lib/utils/cn";

// The Shout wheel. Generated by docs/brand/tools/build-brand.py; edit the
// geometry there, not the SVG in public/brand. Under 32 px the full wheel
// turns to mush, so it switches to the four-spoke version.
// The panel's copy is Daybook navy and gold, with a pale-blue twin for dark
// mode (build-brand.py → PANEL).
export function BrandMark({ size = 28, className }: { size?: number; className?: string }) {
  const base = size < 32 ? "/brand/logo-glyph-small" : "/brand/logo-glyph";
  const common = { alt: "", "aria-hidden": true, width: size, height: size, unoptimized: true } as const;
  return (
    <>
      <Image {...common} src={`${base}.svg`} className={cn("shrink-0 select-none dark:hidden", className)} />
      <Image {...common} src={`${base}-on-dark.svg`} className={cn("hidden shrink-0 select-none dark:block", className)} />
    </>
  );
}

// Wheel + wordmark. "Shout" is Daybook gold (lighter in dark mode).
export function BrandLockup({ className }: { className?: string }) {
  return (
    <span className={cn("inline-flex items-center gap-2.5", className)}>
      <BrandMark size={36} />
      <span className="font-display text-xl font-bold leading-none tracking-[-0.02em] text-foreground">
        Job
        <span className="text-gold">
          Shout
        </span>
      </span>
    </span>
  );
}
